const plantingPhotos={"tomato": {"url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Tomato_je.jpg/960px-Tomato_je.jpg", "source": "https://commons.wikimedia.org/wiki/File:Tomato_je.jpg", "author": "Softeis", "license": "CC BY-SA 3.0", "licenseUrl": "http://creativecommons.org/licenses/by-sa/3.0/"}, "cucumber": {"url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/ARS_cucumber.jpg/960px-ARS_cucumber.jpg", "source": "https://commons.wikimedia.org/wiki/File:ARS_cucumber.jpg", "author": "Stephen Ausmus, USDA ARS", "license": "Public domain", "licenseUrl": ""}, "carrot": {"url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Vegetable-Carrot-Bundle-wStalks.jpg/960px-Vegetable-Carrot-Bundle-wStalks.jpg", "source": "https://commons.wikimedia.org/wiki/File:Vegetable-Carrot-Bundle-wStalks.jpg", "author": "Evan-Amos", "license": "Public domain", "licenseUrl": ""}, "radish": {"url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Radish_3371103037_4ab07db0bf_o.jpg/960px-Radish_3371103037_4ab07db0bf_o.jpg", "source": "https://commons.wikimedia.org/wiki/File:Radish_3371103037_4ab07db0bf_o.jpg", "author": "Self, en:User:Jengod", "license": "Public domain", "licenseUrl": ""}, "dill": {"url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Liat_Portal_for_Foodie_Disorder_-_Fresh_Dill.jpg/960px-Liat_Portal_for_Foodie_Disorder_-_Fresh_Dill.jpg", "source": "https://commons.wikimedia.org/wiki/File:Liat_Portal_for_Foodie_Disorder_-_Fresh_Dill.jpg", "author": "HaJunkiyada", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0"}, "parsley": {"url": "https://upload.wikimedia.org/wikipedia/commons/b/bf/Parsley100.jpg", "source": "https://commons.wikimedia.org/wiki/File:Parsley100.jpg", "author": "Tharish", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0"}};
let plantingSelection=null,plantingBusy=false;
gamePlant=async function(plot){closeFieldMenu();try{const userId=account?.id;const data=await api('planting-offers',{plot});if(account?.id!==userId)return;plantingSelection={plot,offers:data.offers,keys:Object.fromEntries(data.offers.map(x=>[x.id,crypto.randomUUID()]))};modalForm('Что вырастим на грядке?',`<p>Грядка №${plot} · вся площадь. Выберите овощ — мы подготовим необходимое количество семян и отправим садовнику задачу.</p><p class="planting-payment-note">После выбора покажем стоимость и запросим подтверждение. До подтверждения ничего не списывается. Семена, посадка${data.offers[0]?.quote.prepare?' и подготовка почвы':''} включены.</p><div class="planting-photo-grid">${data.offers.map(c=>{const photo=plantingPhotos[c.id];return `<article class="planting-photo-card"><img src="${esc(photo.url)}" alt="${esc(c.name)} — пример будущего урожая" loading="eager" referrerpolicy="no-referrer"><div><h3>${esc(c.name)}</h3><p>Вся грядка · работа ~${c.quote.minutes} мин.</p><button type="button" class="btn planting-buy" data-crop="${c.id}" onclick="plantingBuy('${c.id}',this)">Посадить · ${money(c.quote.price)}</button></div></article>`}).join('')}</div><p class="note">Фото показывает культуру, а не гарантированный результат или конкретный сорт. Время в задаче учитывает свободную смену 09:00–19:00. Таймер относится к посадке, не к созреванию.</p><details><summary>Авторы фотографий</summary>${data.offers.map(c=>{const p=plantingPhotos[c.id];return `<p>${esc(c.name)}: <a href="${esc(p.source)}" target="_blank" rel="noopener">${esc(p.author)}</a> · ${p.licenseUrl?`<a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener">${esc(p.license)}</a>`:esc(p.license)}</p>`}).join('')}</details>`,()=>{})}catch(e){toast(e.message)}};
async function plantingBuy(crop,button){
 if(plantingBusy||!plantingSelection)return;
 const selection=plantingSelection,offer=selection.offers.find(x=>x.id===crop),userId=account?.id;if(!offer)return;
 plantingBusy=true;button.disabled=true;const original=button.textContent;button.textContent='Проверяем баланс…';
 try{const wallet=await api('wallet');if(account?.id!==userId||selection!==plantingSelection)return;walletData=wallet;
 const balance=Number(wallet.balance_kopecks),shortfall=Math.max(0,offer.quote.price-balance);
 modalForm('Посадить: '+esc(offer.name)+'?',`<img class="planting-confirm-photo" src="${esc(plantingPhotos[crop].url)}" alt="${esc(offer.name)}"><p>Грядка №${selection.plot} · вся площадь. Семена, посадка${offer.quote.prepare?' и подготовка почвы':''} включены.</p><div class="planting-payment-note"><p>Стоимость: <b>${money(offer.quote.price)}</b></p><p>Ваш демобаланс: <b>${money(balance)}</b></p><p>${shortfall?'Не хватает: <b>'+money(shortfall)+'</b>':'После оплаты останется: <b>'+money(balance-offer.quote.price)+'</b>'}</p></div><p>Работа займёт около ${offer.quote.minutes} мин. Срок выполнения назначим по свободной смене садовника; он появится в задаче и над грядкой.</p><p>Это демооплата. Реальные деньги не списываются.</p>${shortfall?'<div class="form-error" role="alert">Недостаточно демосредств. Пополните баланс, затем вернитесь к посадке.</div><button type="button" class="btn" onclick="modal.close();location.hash=&quot;#wallet&quot;;walletForm(&quot;topup&quot;)">＋ Пополнить демобаланс</button>':`<button type="button" class="btn planting-confirm" onclick="confirmPlanting('${crop}',this)">Подтвердить и оплатить ${money(offer.quote.price)}</button>`}<button type="button" class="btn light" onclick="gamePlant(${selection.plot})">Назад к овощам</button>`,()=>{});
 }catch(e){toast(e.message)}finally{plantingBusy=false;button.disabled=false;button.textContent=original}
}
async function confirmPlanting(crop,button){
 if(plantingBusy||!plantingSelection)return;const selection=plantingSelection,offer=selection.offers.find(x=>x.id===crop);if(!offer)return;
 plantingBusy=true;button.disabled=true;const original=button.textContent;button.textContent='Отправляем садовнику…';
 try{const data=await api('planting-buy',{plot:selection.plot,crop,price:offer.quote.price,key:selection.keys[crop]});
 walletData=null;modal.close();openFarmBed(selection.plot,'overview');await loadOperations();render();
 modalForm('🌱 Посадка заказана!',`<p><b>${esc(offer.name)}</b> · грядка №${selection.plot}</p><p>Оплачено демобалансом: <b>${money(data.order.price_kopecks)}</b>.</p><p>Задача назначена садовнику. Плановое завершение: <b>${fmt(data.order.finish_by)}</b>.</p><p>Обратный отсчёт появится над грядкой. «Посажено» — после подтверждения выполнения.</p><button type="button" class="btn" onclick="modal.close();openFarmBed(${selection.plot},'overview')">К своей грядке</button><button type="button" class="btn light" onclick="modal.close();location.hash='#orders'">Посмотреть задачу</button>`,()=>{});
 }catch(e){toast(e.message);button.disabled=false;button.textContent=original}finally{plantingBusy=false}
}
const beforePlantingOrderCard=orderCard;
orderCard=function(o){const html=beforePlantingOrderCard(o);if(o.service_code!=='plant_package')return html;const active=!['done','cancelled'].includes(o.status),photo=plantingPhotos[o.planting_crop];return html.replace('<article class="panel">',`<article class="panel planting-task">${photo?`<img class="planting-task-photo" src="${esc(photo.url)}" alt="${esc(o.title)}" referrerpolicy="no-referrer">`:''}${active?`<div class="planting-timer"><span>⏳ До планового завершения посадки</span><strong data-planting-deadline="${esc(o.finish_by)}">Считаем время…</strong><small>${o.status==='working'?'Садовник выполняет работу':'Задача в очереди садовника'}. По окончании таймера потребуется подтверждение выполнения.</small></div>`:''}`)};
function updatePlantingTimers(){document.querySelectorAll('[data-planting-deadline]').forEach(el=>{const seconds=Math.ceil((Date.parse(el.dataset.plantingDeadline)-Date.now())/1000);if(!Number.isFinite(seconds)){el.textContent='Уточняем срок';return}el.textContent=seconds<=0?'Срок наступил · ждём отчёт':`${Math.floor(seconds/3600)}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`})}
setInterval(()=>{if(!document.hidden)updatePlantingTimers()},1000);farmViews.add(updatePlantingTimers);
const beforePackageRoomService=roomService;
roomService=function(p,code,icon,title,description){if(code==='plant')return roomTile('🌱','Посадить овощи','Фотографии культур, семена и работа одним заказом',`gamePlant(${p.id})`,'Выбрать культуру и увидеть полную цену');return beforePackageRoomService(p,code,icon,title,description)};
